options.script:
try{const focus='$service';const isAll=!focus||focus==='.+'||focus.indexOf('$')===0;
const series=data.series&&data.series[0];if(!series){return {data:[],layout:{annotations:[{text:'no data',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const F=Object.fromEntries(series.fields.map(f=>[f.name,f.values||[]]));
const cs=F.client||[],ss=F.server||[],cops=F.client_operation_name||[],sops=F.server_operation_name||[],fl=F.failed||[],vs=F.Value||[];
if(!cs.length){return {data:[],layout:{annotations:[{text:'no rows',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
let reachable=null;if(!isAll){const adj=new Map();for(let i=0;i<cs.length;i++){if(!adj.has(cs[i]))adj.set(cs[i],new Set());adj.get(cs[i]).add(ss[i]);}reachable=new Set([focus]);const q=[focus];while(q.length){const n=q.shift();for(const nx of (adj.get(n)||[])){if(!reachable.has(nx)){reachable.add(nx);q.push(nx);}}}}
const rows=[];const aggMap=new Map();
for(let i=0;i<cs.length;i++){if(!isAll&&!(reachable&&reachable.has(cs[i])))continue;const k=cs[i]+'|'+(cops[i]||'(unset)')+'|'+ss[i]+'|'+(sops[i]||'(unset)');const f=String(fl[i])==='true';const v=Number(vs[i])||0;const e=aggMap.get(k)||{c:cs[i],s:ss[i],co:cops[i]||'(unset)',so:sops[i]||'(unset)',ok:0,fail:0};if(f)e.fail+=v;else e.ok+=v;aggMap.set(k,e);}
for(const e of aggMap.values())rows.push(e);
if(!rows.length){return {data:[],layout:{annotations:[{text:'no flow reachable from '+focus,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
// Build node maps
const leftIdx={},rightIdx={};let n=0;
const leftLabels=[],rightLabels=[],nodeColors=[];
// Service color palette
const svcColors=['#5794F2','#73BF69','#B877D9','#FF9830','#8AB8FF','#1F60C4','#37872D','#F2CC0C','#FA6400','#C4162A','#E0B400','#3B7EE0'];
const svcColorMap=new Map();
const getSvcColor=svc=>{if(!svcColorMap.has(svc)){svcColorMap.set(svc,svcColors[svcColorMap.size%svcColors.length]);}return svcColorMap.get(svc);};
for(const r of rows){const lk=r.c+'\u00a0::\u00a0'+r.co;if(!(lk in leftIdx)){leftIdx[lk]=n++;leftLabels.push(lk);nodeColors.push(getSvcColor(r.c));}}
for(const r of rows){const rk=r.s+'\u00a0::\u00a0'+r.so;if(!(rk in rightIdx)){rightIdx[rk]=n++;rightLabels.push(rk);nodeColors.push(getSvcColor(r.s));}}
const labels=[...leftLabels,...rightLabels];
const src=[],tgt=[],val=[],lc=[],cd=[];
for(const r of rows){const lk=r.c+'\u00a0::\u00a0'+r.co;const rk=r.s+'\u00a0::\u00a0'+r.so;const total=r.ok+r.fail;if(total<=0)continue;const errPct=r.fail/total;src.push(leftIdx[lk]);tgt.push(rightIdx[rk]);val.push(total);// Color: green at 0% errors, red at 10%+
const tintR=Math.min(255,Math.round(80+errPct*1750));const tintG=Math.max(60,Math.round(180-errPct*1200));const tintB=Math.max(60,Math.round(120-errPct*800));lc.push(`rgba(${tintR},${tintG},${tintB},0.50)`);cd.push(r.c+'.'+r.co+' → '+r.s+'.'+r.so+'<br>req/s: '+total.toFixed(3)+'<br>error %: '+(errPct*100).toFixed(2)+'<br>failed/s: '+r.fail.toFixed(3));}
return {data:[{type:'sankey',orientation:'h',arrangement:'snap',valueformat:'.3f',valuesuffix:' rps',node:{label:labels,pad:18,thickness:18,color:nodeColors,line:{width:0}},link:{source:src,target:tgt,value:val,color:lc,customdata:cd,hovertemplate:'%{customdata}<extra></extra>'}}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da',size:11},margin:{l:10,r:10,t:10,b:10}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}]}};}

try{const focusVar='$service';const isAll=!focusVar||focusVar==='.+'||focusVar.indexOf('$')===0;
const series=data.series&&data.series[0];if(!series){return {data:[],layout:{annotations:[{text:'no data',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const F=Object.fromEntries(series.fields.map(f=>[f.name,f.values||[]]));
const cs=F.client||[],ss=F.server||[],cops=F.client_operation_name||[],sops=F.server_operation_name||[],fl=F.failed||[],vs=F.Value||[];
if(!cs.length){return {data:[],layout:{annotations:[{text:'no rows',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
// Aggregate edges with same (clientNode, serverNode) summing ok+fail across operations? No — we want OPERATION-level resolution. Each edge is unique.
const edges=[];const nodeKey=(svc,op)=>svc+'\u00a0::\u00a0'+op;
const aggMap=new Map();
for(let i=0;i<cs.length;i++){const k=cs[i]+'|'+(cops[i]||'(unset)')+'|'+ss[i]+'|'+(sops[i]||'(unset)');const f=String(fl[i])==='true';const v=Number(vs[i])||0;const e=aggMap.get(k)||{c:cs[i],s:ss[i],co:cops[i]||'(unset)',so:sops[i]||'(unset)',ok:0,fail:0};if(f)e.fail+=v;else e.ok+=v;aggMap.set(k,e);}
for(const e of aggMap.values()){const fromN=nodeKey(e.c,e.co);const toN=nodeKey(e.s,e.so);edges.push({fromN,toN,c:e.c,s:e.s,total:e.ok+e.fail,fail:e.fail});}
// Find root service. If focus, use that. Else pick service with most outgoing traffic.
let root=focusVar;
if(isAll){const out=new Map();for(const e of edges){out.set(e.c,(out.get(e.c)||0)+e.total);}let maxV=-1;for(const [k,v] of out){if(v>maxV){maxV=v;root=k;}}}
// BFS from any node belonging to root service. Level = depth in BFS.
const nodeLevel=new Map();const adjOut=new Map();
for(const e of edges){if(!adjOut.has(e.fromN))adjOut.set(e.fromN,[]);adjOut.get(e.fromN).push(e);}
// Find all root nodes (any node prefixed with root::)
const rootNodes=new Set();for(const e of edges){if(e.c===root)rootNodes.add(e.fromN);}
if(rootNodes.size===0){return {data:[],layout:{annotations:[{text:'no edges originating from '+root,showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const queue=[];for(const r of rootNodes){nodeLevel.set(r,0);queue.push(r);}
while(queue.length){const n=queue.shift();const lvl=nodeLevel.get(n);for(const e of (adjOut.get(n)||[])){if(!nodeLevel.has(e.toN)||nodeLevel.get(e.toN)>lvl+1){nodeLevel.set(e.toN,lvl+1);queue.push(e.toN);}}}
// Layout: layered. nodes at (level, slot).
const layers={};for(const [node,lvl] of nodeLevel){if(!layers[lvl])layers[lvl]=[];layers[lvl].push(node);}
const maxLvl=Math.max(...Object.keys(layers).map(Number));
const pos={};
for(let lvl=0;lvl<=maxLvl;lvl++){const nodes=(layers[lvl]||[]).sort();const n=nodes.length;for(let i=0;i<n;i++){const x=lvl;const y=n>1?(i-(n-1)/2):0;pos[nodes[i]]={x,y};}}
if(Object.keys(pos).length===0){return {data:[],layout:{annotations:[{text:'no reachable nodes',showarrow:false,font:{color:'#888'}}],paper_bgcolor:'rgba(0,0,0,0)'}};}
const svcColors=['#5794F2','#73BF69','#B877D9','#FF9830','#8AB8FF','#1F60C4','#37872D','#F2CC0C','#FA6400','#C4162A','#E0B400','#3B7EE0'];
const svcColorMap=new Map();const getSvcColor=svc=>{if(!svcColorMap.has(svc)){svcColorMap.set(svc,svcColors[svcColorMap.size%svcColors.length]);}return svcColorMap.get(svc);};
// Build edge traces (one trace per edge so colors can vary)
const traces=[];
for(const e of edges){if(!pos[e.fromN]||!pos[e.toN])continue;const errPct=e.total>0?e.fail/e.total:0;const tintR=Math.min(255,Math.round(80+errPct*1750));const tintG=Math.max(60,Math.round(180-errPct*1200));const tintB=Math.max(60,Math.round(120-errPct*800));const widthHint=Math.min(8,1+Math.log10(1+e.total*1000));const a=pos[e.fromN],b=pos[e.toN];// Bezier-ish curve via 1 mid-point
const midX=(a.x+b.x)/2;const midY=(a.y+b.y)/2;const xs=[a.x,midX,b.x];const ys=[a.y,midY,b.y];traces.push({type:'scatter',mode:'lines',x:xs,y:ys,line:{color:`rgba(${tintR},${tintG},${tintB},0.7)`,width:widthHint,shape:'spline'},hoverinfo:'text',text:e.fromN+' → '+e.toN+'<br>req/s: '+e.total.toFixed(3)+'<br>error %: '+(errPct*100).toFixed(2),showlegend:false});}
// Nodes trace
const nx=[],ny=[],ntext=[],ncolor=[],ncustom=[];
for(const [node,p] of Object.entries(pos)){const svc=node.split('\u00a0::\u00a0')[0];const op=node.split('\u00a0::\u00a0')[1]||'';nx.push(p.x);ny.push(p.y);ntext.push(svc+'<br>'+op);ncolor.push(getSvcColor(svc));ncustom.push(node);}
traces.push({type:'scatter',mode:'markers+text',x:nx,y:ny,text:ntext,textposition:'middle right',marker:{size:24,color:ncolor,line:{width:2,color:'#1f2026'}},textfont:{size:11,color:'#d8d9da'},customdata:ncustom,hovertemplate:'%{customdata}<extra></extra>',showlegend:false});
return {data:traces,layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',xaxis:{visible:false,zeroline:false,showgrid:false,range:[-0.5,maxLvl+1.2]},yaxis:{visible:false,zeroline:false,showgrid:false,scaleanchor:'x',scaleratio:0.6},margin:{l:5,r:200,t:30,b:5},title:{text:'Pipeline rooted at: <b>'+root+'</b>',font:{color:'#d8d9da',size:13}},font:{color:'#d8d9da'}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}]}};}

try{const a=data.series&&data.series[0],b=data.series&&data.series[1];if(!a){return {data:[]};}
const FA=Object.fromEntries(a.fields.map(f=>[f.name,f.values||[]]));
const FB=b?Object.fromEntries(b.fields.map(f=>[f.name,f.values||[]])):{};
const cs=FA.client||[],ss=FA.server||[],cops=FA.client_operation_name||[],sops=FA.server_operation_name||[],vs=FA.Value||[];
const rowKeys=[...new Set(cs.map((c,i)=>c+'\u00a0::\u00a0'+(cops[i]||'(unset)')))].sort();
const colKeys=[...new Set(ss.map((s,i)=>s+'\u00a0::\u00a0'+(sops[i]||'(unset)')))].sort();
const rIdx=Object.fromEntries(rowKeys.map((n,i)=>[n,i]));
const cIdx=Object.fromEntries(colKeys.map((n,i)=>[n,i]));
const Z=rowKeys.map(()=>colKeys.map(()=>null));
for(let i=0;i<cs.length;i++){const r=rIdx[cs[i]+'\u00a0::\u00a0'+(cops[i]||'(unset)')];const c=cIdx[ss[i]+'\u00a0::\u00a0'+(sops[i]||'(unset)')];if(r!=null&&c!=null)Z[r][c]=Number(vs[i])||0;}
// Failure rates
const FK={};if(b){const c2=FB.client||[],s2=FB.server||[],co2=FB.client_operation_name||[],so2=FB.server_operation_name||[],v2=FB.Value||[];for(let i=0;i<c2.length;i++){const k=c2[i]+'\u00a0::\u00a0'+(co2[i]||'(unset)')+'->'+s2[i]+'\u00a0::\u00a0'+(so2[i]||'(unset)');FK[k]=Number(v2[i])||0;}}
const hover=rowKeys.map(r=>colKeys.map(c=>{const ri=rIdx[r],ci=cIdx[c];const v=Z[ri][ci];if(v==null)return r+' → '+c+'<br>(no traffic)';const fr=FK[r+'->'+c]||0;return r+' → '+c+'<br>'+v.toFixed(3)+' rps<br>error %: '+(fr*100).toFixed(2);}));
return {data:[{type:'heatmap',z:Z,x:colKeys,y:rowKeys,colorscale:[[0,'#1f2026'],[0.0001,'#0d1b3a'],[0.2,'#1f60c4'],[0.5,'#73bf69'],[0.8,'#ff9830'],[1,'#e02f44']],showscale:true,colorbar:{title:'rps',thickness:10,tickfont:{color:'#d8d9da'},titlefont:{color:'#d8d9da'}},hoverinfo:'text',text:hover,xgap:1,ygap:1}],layout:{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#d8d9da',size:10},margin:{l:240,r:10,t:30,b:140},xaxis:{title:'server.op',side:'top',tickangle:-50,tickfont:{size:10}},yaxis:{title:'client.op',autorange:'reversed',tickfont:{size:10}}}};
}catch(e){return {data:[],layout:{annotations:[{text:'script error: '+e.message,showarrow:false,font:{color:'#e02f44'}}]}};}
